  int r=threadIdx.x>>4, c=(threadIdx.x&15)*8; unsigned long long pol=pel();
  int t=blockIdx.x; float xa[8], xb[8], wv[8];
  if(t<T){bool isk=t>=n_tiles; int tile=isk?t-n_tiles:t; ld8((isk?k:q)+((size_t)tile*16+r)*D+c,xa);}
