template <bool LOAD_S>
__device__ __forceinline__ void do_tile(const float* __restrict__ q, const float* __restrict__ k,
                                        const float* __restrict__ wq, const float* __restrict__ wk,
                                        float* __restrict__ qo, float* __restrict__ ko,
                                        int t, int n_tiles, float eps, uint64_t pol_out) {
    const bool is_k = t >= n_tiles;
    const int tile = is_k ? t - n_tiles : t;
    const float* __restrict__ x = is_k ? k : q;
    const float* __restrict__ w = is_k ? wk : wq;
    float* __restrict__ y = is_k ? ko : qo;
    const int r = threadIdx.x >> 4;
    const int c = (threadIdx.x & 15) * 8;
    const size_t off = ((size_t)tile * ROWS + r) * D + c;
    const int head = (tile % GROUPS) * ROWS + r;
    float xv[8], wv[8], yv[8];
    if (LOAD_S) {
        ld8_h(x + off, xv, POL_EVICT_FIRST);
        ld8_nc(w + (size_t)head * D + c, wv);
    } else {
        ld8(x + off, xv);
        ld8(w + (size_t)head * D + c, wv);
    }
    float s = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) s = fmaf(xv[i], xv[i], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.0f / (float)D) + eps);
#pragma unroll
    for (int i = 0; i < 8; ++i) yv[i] = (xv[i] * inv) * wv[i];
    st8_h(y + off, yv, pol_out);
}

// One resident wave, grid-stride over 16-row tiles (Q tiles then K tiles).
__global__ void __launch_bounds__(THREADS, 8)
qk_rms_onewave(const float* __restrict__ q, const float* __restrict__ k,
               const float* __restrict__ wq, const float* __restrict__ wk,
               float* __restrict__ qo, float* __restrict__ ko, int n_tiles, float eps) {
    const uint64_t pol_out = pol_evict_last();
    const int T = 2 * n_tiles;
    for (int t = blockIdx.x; t < T; t += gridDim.x)
        do_tile<true>(q, k, wq, wk, qo, ko, t, n_tiles, eps, pol_out);
}

// One-shot (r6 M/L path): one 16-row tile per CTA.
__global__ void __launch_bounds__(THREADS, 8)
qk_rms_oneshot(const float* __restrict__ q, const float* __restrict__ k,
               const float* __restrict__ wq, const float* __restrict__ wk,
               float* __restrict__ qo, float* __restrict__ ko, int n_tiles, float eps) {
    do_tile<false>(q, k, wq, wk, qo, ko, blockIdx.x, n_tiles, eps, pol_evict_last());
}
}  // namespace

extern "C" int r10_launch(const float* q, const float* k, const float* wq, const float* wk,
                          float* qo, float* ko, long long n_rows, float eps, int one_wave,
                          int wave_ctas, cudaStream_t stream) {
    const long long n_tiles = n_rows / ROWS;
    if (n_tiles <= 0) return 0;
    const long long total = 2 * n_tiles;
    if (one_wave) {
        const unsigned g = (unsigned)(total < wave_ctas ? total : wave_ctas);
        qk_rms_onewave<<<g, THREADS, 0, stream>>>(q, k, wq, wk, qo, ko, (int)n_tiles, eps);
    } else {
        qk_rms_oneshot<<<(unsigned)total, THREADS, 0, stream>>>(q, k, wq, wk, qo, ko, (int)n_tiles, eps);
    }
    return (int)cudaGetLastError();
}
